fn gtk_app(app: &Application) {
    // --- 1. Estrutura Principal (Main Layout) ---
    // Usaremos um Box vertical para organizar as seções em ordem.
    let main_vbox = Box::new(Orientation::Vertical, 15);
    main_vbox.set_margin_top(25);
    main_vbox.set_margin_bottom(25);
    main_vbox.set_margin_start(25);
    main_vbox.set_margin_end(25);

    // --- 2. Seção de Entrada de Arquivos (File Selection Row) ---
    let file_row_box = Box::new(Orientation::Horizontal, 10);

    // Usando SearchEntry para integrar o campo e o botão de busca de forma nativa
    let file_entry = SearchEntry::builder()
        .placeholder_text("Selecione um arquivo de áudio...")
        .hexpand(true) // Permite que o campo ocupe o espaço disponível
        .build();

    let search_button = Button::builder()
        .icon_name("document-open-symbolic") // Adicionando um ícone para melhor visual
        .tooltip_text("Abrir Arquivo")
        .build();

    // Configurando a ação ao clicar no botão de busca
    let file_entry_clone = file_entry.clone();
    search_button.connect_clicked(move |_| {
        if let Some(path) = openfiledialog_box() {
            file_entry_clone.set_text(path.to_str().unwrap_or(""));
        }
    });

    // Adicionar o botão ao SearchEntry (Isso é um pouco mais complexo no GTK moderno, 
    // mas para manter a simplicidade, vamos seguir o padrão de adicionar widgets adjacentes
    // ou usar o botão do SearchEntry se fosse apenas para "Buscar"). 
    // Vamos manter a lógica de ter um botão externo conectado ao SearchEntry.
    file_row_box.append(&file_entry);
    file_row_box.append(&search_button);


